#include <bits/stdc++.h>
using namespace std;

void hanoi(int n, int from, int by, int to) {
    if (n == 1) {
        cout << from << ' ' << to << '\n';
        return;
    }
    hanoi(n - 1, from, to, by);
    cout << from << ' ' << to << '\n';
    hanoi(n - 1, by, from, to);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;

    cout << ((1LL << N) - 1) << '\n';
    hanoi(N, 1, 2, 3);

    return 0;
}
```

